function parse(s) {
const names={}, inclusive={}, own={};let fn=null, call=false;
for(const line of s.split("\n")){
const m=/^(c?fn)=\((\d+)\)(?: (.*))?$/.exec(line);
if(m){if(m[3])names[m[2]]=m[3];if(m[1]==="fn"){fn=m[2];call=false;}continue;}
if(line.startsWith("calls=")){call=true;continue;}
const cost=/^(?:0x[\da-f]+|[+\-]?\d+|\*)\s+(?:[+\-]?\d+|\*)\s+(\d+)\s*$/i.exec(line);
if(cost){if(fn===null)throw Error("cost without function");const n=Number(cost[1]);inclusive[fn]=(inclusive[fn]||0)+n;if(!call)own[fn]=(own[fn]||0)+n;call=false;}
}
const summary=Number(/^summary: (\d+)/m.exec(s)[1]);
const selfTotal=Object.values(own).reduce((a,b)=>a+b,0);
if(selfTotal!==summary)throw Error("self total mismatch "+selfTotal+" "+summary);
const selected=Object.entries(names).filter(([id,n])=>/decode_block|bwt::build$|room_segments|c30cg::measured/.test(n)).map(([id,name])=>({name,inclusive:inclusive[id]||0,self:own[id]||0}));
return {summary,selfTotal,selected};
}

